import { revealCells } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}
function rangeError(fn: () => void, message: string): void {
  try { fn(); } catch (error) {
    assert(error instanceof RangeError, message);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const mask = [false, false, true, false, false, false, false, false, false];
const snapshot = mask.slice();
const result = revealCells(mask, 3, 3, 1, 1, 1);
equal(result, [false, true, true, true, true, true, false, true, false], "reveals center and cells exactly on radius boundary while preserving true cells");
equal(mask, snapshot, "does not mutate input mask");
assert(result !== mask, "returns a fresh mask");
result[0] = true;
assert(mask[0] === false, "output mutation does not affect input");

equal(revealCells([false, true, false, false], 2, 2, 0, 0, 0), [true, true, false, false], "zero radius reveals an exactly centered integer cell");
equal(revealCells([false, false, false, false], 2, 2, 0.5, 0.5, Math.sqrt(0.5)), [true, true, true, true], "fractional center includes cells on squared-distance boundary");
equal(revealCells([false, true], 2, 1, 10, 10, 0), [false, true], "retains existing cells when reveal reaches none");

const empty: boolean[] = [];
const emptyResult = revealCells(empty, 0, 0, 0, 0, 0);
equal(emptyResult, [], "accepts valid empty zero-by-zero mask");
assert(emptyResult !== empty, "empty result is fresh");
equal(revealCells([], 0, 3, 0, 0, 1), [], "accepts zero-width masks with matching length");

const invalidCalls: Array<() => void> = [
  () => revealCells([], -1, 0, 0, 0, 0),
  () => revealCells([], 0, -1, 0, 0, 0),
  () => revealCells([], 1.5, 0, 0, 0, 0),
  () => revealCells([], 0, 2.5, 0, 0, 0),
  () => revealCells([false], 2, 1, 0, 0, 0),
  () => revealCells([], 0, 0, NaN, 0, 0),
  () => revealCells([], 0, 0, Infinity, 0, 0),
  () => revealCells([], 0, 0, 0, -Infinity, 0),
  () => revealCells([], 0, 0, 0, 0, -1),
  () => revealCells([], 0, 0, 0, 0, NaN),
  () => revealCells([], 0, 0, 0, 0, Infinity),
];
invalidCalls.forEach((call, index) => rangeError(call, `invalid argument case ${index} throws RangeError`));

